/// every built-in profile (E6 at birth, E8 elsewhere).
HostExtension _yoclipExtension() => HostExtension(
  name: 'yoclip',
  tools: [
    AgentTool(
      name: 'yoclip_cut',
      label: 'yoclip_cut',
      description: 'YoClip clip tool (the host extension scenario).',
      parameters: {
        'type': 'object',
        'properties': {
          'shape': {'type': 'string', 'description': 'The clip shape.'},
