    ),
  ],
  profileStates: {
    for (final profile in builtInProfiles.keys)
      profile: const CapabilityOffState(
        'the yoclip toolset ships with the yoclip host only',
      ),
    'yoclip-host': const CapabilityOnState(),
  },
);

