      name: 'write',
      arguments: {
        'path': '/w/notes/runbook.md',
        'content': 'deploy checklist: step 1\n',
      },
    ),
  ]),
  _textTurn('b' * 400, tokens: 5000),
  _textTurn(turn2Text ?? 'c' * 400, tokens: 5000),
  _textTurn('Continuing after compaction.', tokens: 100),
